// Changes (PF1 "buff targets"), context notes and @-formula autocomplete for the character builder.
// Target / bonus-type lists and the roll data key layout come from formula-data.js (generated by
// scripts/extract_pf1_formula_data.mjs). Autocomplete follows the approach of the Autocomplete
// Inline Properties Foundry module (MIT): walk the roll data one path segment at a time.
"use strict"

// bonus types that stack with themselves (pf1.config.stackingBonusTypes, plus pf1spheres' cap)
const STACKING_TYPES = new Set(["untyped", "untypedPerm", "dodge", "racial", "circumstance", "sphereCLCap"])
const BUFF_KINDS = { temp: "Temporary", perm: "Permanent", spell: "Spell", feat: "Feat", item: "Item" }
const DURATION_UNITS = { "": "—", round: "Rounds", minute: "Minutes", hour: "Hours", day: "Days", turn: "Turns", inst: "Instantaneous", perm: "Permanent", seeText: "See text", spec: "Special" }
const SIZE_INDEX = { fine: 0, dim: 1, tiny: 2, sm: 3, med: 4, lg: 5, huge: 6, grg: 7, col: 8 }

// ---------- target lists ----------

function targetOptions() {
  if (targetOptions.cache) return targetOptions.cache
  const groups = {}
  for (const [key, label, cat] of PF1_FORMULA.targets) (groups[cat] ??= []).push([key, label])
  // per-skill targets are added by Foundry at runtime from the actor's skills
  groups.skill = Object.entries(SKILLS).map(([k, [label]]) => [`skill.${k}`, label])
  return (targetOptions.cache = Object.entries(groups).map(([cat, list]) => [PF1_FORMULA.categories[cat] ?? cat, list]))
}
function targetLabel(key) {
  for (const [, list] of targetOptions()) for (const [k, l] of list) if (k === key) return l
  return key
}
function noteTargetOptions() {
  const groups = {}
  for (const [key, label, cat] of PF1_FORMULA.noteTargets) (groups[cat] ??= []).push([key, label])
  groups.skill = Object.entries(SKILLS).map(([k, [label]]) => [`skill.${k}`, label])
  return Object.entries(groups).map(([cat, list]) => [PF1_FORMULA.noteCategories[cat] ?? PF1_FORMULA.categories[cat] ?? cat, list])
}

// ---------- roll data ----------

// Values the builder knows, laid out like the actor's getRollData() in Foundry
function buildRollData(c) {
  const s = state
  const abilities = {}
  for (const k of ABL) {
    const base = num(s.abilities[k])
    abilities[k] = { value: base, total: c.abl[k].total, mod: c.abl[k].mod, base: c.abl[k].total, baseMod: c.abl[k].mod, damage: 0, drain: 0, penalty: 0, userPenalty: 0 }
  }
  const skills = {}
  for (const [k, [, , rt, acp]] of Object.entries(SKILLS)) {
    const rank = num(s.skills[k])
    skills[k] = { rank, mod: skillTotal(k, rank, c), ability: skillAbl(k), cs: c.classSkills.has(k), rt: !!rt, acp: !!acp }
  }
  const classes = {}
  for (const cl of s.classes) {
    if (num(cl.level) <= 0) continue
    const tag = tagFor(cl.name || "class")
    classes[tag] = { name: cl.name, level: num(cl.level), unlevel: num(cl.level), hd: num(cl.hd), hitDice: num(cl.level), bab: cl.bab, type: "base", isBase: true, isMythic: false, mythicTier: 0, fc: { hp: num(cl.fcbHp), skill: num(cl.fcbSkill), alt: 0 } }
  }
  const save = (k, abl) => ({ base: c.saves[k], total: c.saveTotals[k], ability: abl })
  const rd = {
    abilities,
    attributes: {
      hd: { total: c.hd },
      bab: { total: c.bab },
      hp: { max: c.hp, value: c.hp, temp: 0, nonlethal: 0 },
      ac: { normal: { total: c.ac }, touch: { total: c.touch }, flatFooted: { total: c.flat } },
      cmb: { total: c.cmb },
      cmd: { total: c.cmd },
      init: { total: c.init },
      savingThrows: { fort: save("fort", "con"), ref: save("ref", "dex"), will: save("will", "wis") },
      speed: { land: { base: num(s.race.speed), total: c.speed } },
      naturalAC: 0,
      energyDrain: 0,
    },
    details: { level: { value: c.hd }, bonusFeatFormula: String(num(s.bonusFeats) || ""), bonusSkillRankFormula: s.bonusSkillFormula },
    skills,
    classes,
    size: SIZE_INDEX[s.race.size] ?? 4,
    currency: { ...s.currency },
  }
  if (s.spheresModule) {
    const am = (k) => (k ? c.abl[k].mod : 0)
    rd.spheres = {
      cl: { total: c.spheres.cl, base: c.spheres.cl },
      msb: { total: c.spheres.msb, base: c.spheres.msb },
      msd: { total: c.spheres.msd, base: c.spheres.msb },
      concentration: { total: c.spheres.concentration },
      cam: am(s.sphere.casting),
      pam: am(s.sphere.practitioner),
      oam: am(s.sphere.operative),
    }
  }
  return rd
}

// Shape from Foundry (types only) overlaid with the values above, for autocomplete
function rollDataTree(rd) {
  const shape = PF1_FORMULA.rollDataShape ?? {}
  const merge = (sh, live) => {
    if (live !== undefined && (live === null || typeof live !== "object")) return live
    const out = {}
    const shapeObj = sh && typeof sh === "object" && !Array.isArray(sh) ? sh : {}
    for (const k of new Set([...Object.keys(shapeObj), ...Object.keys(live ?? {})])) {
      if (k === "*") continue
      out[k] = merge(shapeObj[k] ?? shapeObj["*"], live?.[k])
    }
    // keys only in the shape keep their type name ("number"), shown as "set in Foundry"
    if (!Object.keys(out).length && typeof sh === "string") return { __type: sh }
    return out
  }
  return merge(shape, rd)
}

// ---------- formulas ----------

// Evaluates simple roll formulas for the preview: numbers, + - * / %, parentheses, @paths that
// resolve to numbers, and floor/ceil/round/min/max/abs. Dice or unknown paths return null.
function evalFormula(formula, rd) {
  const f = String(formula ?? "").trim()
  if (!f) return { value: 0 }
  let unknown = false
  const expr = f
    .replace(/@([\w.~]+)/g, (_, path) => {
      const v = path.split(".").reduce((o, k) => o?.[k], rd)
      if (typeof v === "number") return `(${v})`
      if (typeof v === "boolean") return v ? "1" : "0"
      unknown = true
      return "0"
    })
    .replace(/\b(floor|ceil|round|min|max|abs)\(/g, "Math.$1(")
  if (unknown || !/^(?:[\d+\-*/%(). ,]|Math\.(?:floor|ceil|round|min|max|abs))*$/.test(expr)) return { value: null }
  try {
    const v = Function(`"use strict"; return (${expr})`)()
    return Number.isFinite(v) ? { value: v } : { value: null }
  } catch {
    return { value: null }
  }
}

// Everything that currently applies: features, sphere talents (with the module on) and active buffs
function activeChangeSources() {
  const out = []
  for (const f of state.features) out.push(f)
  if (state.spheresModule) for (const t of state.talents) out.push(t)
  for (const b of state.buffs) if (b.active) out.push(b)
  return out
}

// Sum changes per target with PF1's stacking: same-type bonuses don't stack (highest wins) unless the
// type stacks; penalties always stack. "Set" changes and formulas the preview can't evaluate are skipped.
function changeTotals(rd) {
  const byTarget = {}
  const skipped = []
  for (const src of activeChangeSources())
    for (const ch of src.changes ?? []) {
      if (!ch.target) continue
      const { value } = evalFormula(ch.formula, rd)
      if (value == null || ch.operator === "set") {
        skipped.push(ch)
        continue
      }
      ;((byTarget[ch.target] ??= {})[ch.type || "untyped"] ??= []).push(value)
    }
  const totals = {}
  for (const [target, types] of Object.entries(byTarget)) {
    let sum = 0
    for (const [type, values] of Object.entries(types)) {
      const neg = values.filter((v) => v < 0).reduce((a, v) => a + v, 0)
      const pos = values.filter((v) => v > 0)
      sum += neg + (STACKING_TYPES.has(type) ? pos.reduce((a, v) => a + v, 0) : pos.length ? Math.max(...pos) : 0)
    }
    totals[target] = Math.floor(sum)
  }
  return { totals, skipped }
}

// ---------- autocomplete ----------

let acState = null

function closeAutocomplete() {
  acState?.box.remove()
  acState = null
}

// Path being typed right before the caret, e.g. "abilities.st" in "floor(@abilities.st"
function acContext(el) {
  const before = el.value.slice(0, el.selectionStart ?? el.value.length)
  const m = before.match(/@([\w.~]*)$/)
  return m ? { path: m[1], start: before.length - m[1].length } : null
}

function acItems(path) {
  const tree = rollDataTree(buildRollData(calc()))
  const parts = path.split(".")
  const partial = parts.pop().toLowerCase()
  const node = parts.reduce((o, k) => o?.[k], tree)
  if (!node || typeof node !== "object" || node.__type) return []
  const prefix = parts.length ? parts.join(".") + "." : ""
  return Object.entries(node)
    .filter(([k]) => k !== "__type" && k.toLowerCase().startsWith(partial))
    .map(([k, v]) => {
      const leaf = v === null || typeof v !== "object" || !!v.__type
      const shown = v === null ? "—" : typeof v !== "object" ? String(v) : v.__type ? "set in Foundry" : "{…}"
      return { key: prefix + k, name: k, leaf, shown }
    })
    .sort((a, b) => (a.leaf === b.leaf ? a.name.localeCompare(b.name) : a.leaf ? -1 : 1))
    .slice(0, 200)
}

function renderAutocomplete(el) {
  const ctx = acContext(el)
  if (!ctx) return closeAutocomplete()
  const items = acItems(ctx.path)
  if (!items.length) return closeAutocomplete()
  if (!acState || acState.el !== el) {
    closeAutocomplete()
    const box = h("div", { class: "ac-box", role: "listbox" })
    document.body.append(box)
    acState = { el, box, index: 0 }
  }
  acState.items = items
  acState.ctx = ctx
  acState.index = Math.min(acState.index, items.length - 1)
  const r = el.getBoundingClientRect()
  Object.assign(acState.box.style, { left: `${r.left + scrollX}px`, top: `${r.bottom + scrollY + 2}px`, minWidth: `${Math.max(r.width, 260)}px` })
  acState.box.replaceChildren(
    ...items.map((it, i) =>
      h("div", {
        class: "ac-item" + (i === acState.index ? " active" : ""),
        role: "option",
        "aria-selected": String(i === acState.index),
        onmousedown: (e) => { e.preventDefault(); acceptAutocomplete(i) },
      }, h("span", { class: "ac-key" }, "@" + it.key + (it.leaf ? "" : ".")), h("span", { class: "ac-val" }, it.shown))),
    h("div", { class: "ac-hint" }, "↑↓ to move · Tab or Enter to insert · Esc to close"),
  )
  acState.box.querySelector(".ac-item.active")?.scrollIntoView({ block: "nearest" })
}

function acceptAutocomplete(i = acState.index) {
  const { el, items, ctx } = acState
  const it = items[i]
  const insert = it.key + (it.leaf ? "" : ".")
  const end = el.selectionStart ?? el.value.length
  el.value = el.value.slice(0, ctx.start) + insert + el.value.slice(end)
  const caret = ctx.start + insert.length
  el.setSelectionRange(caret, caret)
  el.dispatchEvent(new Event("input", { bubbles: true }))
  acState.index = 0
  if (it.leaf) closeAutocomplete()
  else renderAutocomplete(el)
}

function attachAutocomplete(el) {
  el.setAttribute("autocomplete", "off")
  el.addEventListener("input", () => renderAutocomplete(el))
  el.addEventListener("click", () => renderAutocomplete(el))
  el.addEventListener("blur", () => setTimeout(() => acState?.el === el && closeAutocomplete(), 100))
  el.addEventListener("keydown", (e) => {
    if (!acState || acState.el !== el) return
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault()
      const n = acState.items.length
      acState.index = (acState.index + (e.key === "ArrowDown" ? 1 : n - 1)) % n
      renderAutocomplete(el)
    } else if (e.key === "Enter" || e.key === "Tab") {
      e.preventDefault()
      acceptAutocomplete()
    } else if (e.key === "Escape") {
      e.preventDefault()
      closeAutocomplete()
    }
  })
  return el
}
// page scrolls move the field away from the list; scrolling the list itself must not close it
window.addEventListener("scroll", (e) => acState && !acState.box.contains(e.target) && closeAutocomplete(), true)
window.addEventListener("resize", closeAutocomplete)

// ---------- editors ----------

function groupedSelect(groups, current, onChange, attrs = {}) {
  const el = h("select", attrs,
    h("option", { value: "", selected: !current }, "Choose…"),
    ...groups.map(([label, list]) => h("optgroup", { label }, list.map(([k, l]) => h("option", { value: k, selected: k === current }, l)))))
  el.addEventListener("change", () => onChange(el.value))
  return el
}

// Targets the builder's preview applies (see calcCore); the rest only take effect in Foundry.
// Built on first use because ABL lives in builder.js, which loads after this file.
let previewTargets
const previewTargetList = () => [
  ...ABL, ...ABL.map((k) => `${k}Mod`), ...ABL.map((k) => `${k}Skills`),
  "bab", "attack", "wattack", "mattack", "rattack", "damage", "wdamage", "mwdamage", "mdamage", "rwdamage", "rdamage",
  "ac", "aac", "sac", "nac", "tac", "ffac", "cmb", "cmd", "init", "fort", "ref", "will", "allSavingThrows", "mhp",
  "skills", "unskills", "landSpeed", "allSpeeds", "bonusFeats", "bonusSkillRanks", "acpA", "acpS", "mDexA",
  "spherecl", "msb", "msd", "sphereConcentration",
]
const TARGET_HINTS = {
  acpA: "Added to the armor's check penalty: use a negative number to reduce it (Armor Training: -1).",
  acpS: "Added to the shield's check penalty: use a negative number to reduce it.",
  mDexA: "Added to the armor's maximum Dexterity bonus.",
  mDexS: "Added to the shield's maximum Dexterity bonus.",
}
function inPreview(target) {
  previewTargets ??= new Set(previewTargetList())
  return !target || previewTargets.has(target) || target.startsWith("skill.")
}

function formulaPreview(formula, target) {
  const { value } = evalFormula(formula, buildRollData(calc()))
  if (value == null) return String(formula ?? "").trim() ? "in Foundry" : ""
  return `= ${signed(Math.floor(value))}${inPreview(target) ? "" : " · Foundry only"}`
}

// Changes + context notes for one item (feature, talent or buff), in a collapsible block
function changesEditor(entry) {
  entry.changes ??= []
  entry.notes ??= []
  const count = entry.changes.length + entry.notes.length
  const typeOpts = Object.entries(PF1_FORMULA.bonusTypes)

  const changeRow = (ch, i) => {
    const preview = h("span", { class: "ch-preview", title: "Value now; targets marked Foundry only aren't in the builder's preview" }, formulaPreview(ch.formula, ch.target))
    const hint = h("div", { class: "note ch-hint" }, TARGET_HINTS[ch.target] ?? "")
    const formula = attachAutocomplete(h("input", { value: ch.formula ?? "", placeholder: "Formula, e.g. 2 or @abilities.str.mod", "aria-label": "Change formula", class: "ch-formula" }))
    formula.addEventListener("input", () => {
      ch.formula = formula.value
      preview.textContent = formulaPreview(ch.formula, ch.target)
      changed()
    })
    const type = h("select", { "aria-label": "Bonus type" }, typeOpts.map(([k, l]) => h("option", { value: k, selected: k === (ch.type || "untyped") }, l)))
    type.addEventListener("change", () => { ch.type = type.value; changed() })
    return h("div", { class: "ch-row" },
      groupedSelect(targetOptions(), ch.target, (v) => {
        ch.target = v
        preview.textContent = formulaPreview(ch.formula, ch.target)
        hint.textContent = TARGET_HINTS[ch.target] ?? ""
        changed()
      }, { "aria-label": "Change target", class: "ch-target" }),
      type,
      formula,
      preview,
      h("button", { class: "small danger", "aria-label": "Remove change", onclick: () => { entry.changes.splice(i, 1); changed(true) } }, "×"),
      hint,
    )
  }
  const noteRow = (n, i) => {
    const text = attachAutocomplete(h("input", { value: n.text ?? "", placeholder: "e.g. +2 vs. poison, or [[@abilities.wis.mod]] vs. fear", "aria-label": "Context note text", class: "ch-formula" }))
    text.addEventListener("input", () => { n.text = text.value; changed() })
    return h("div", { class: "ch-row" },
      groupedSelect(noteTargetOptions(), n.target, (v) => { n.target = v; changed() }, { "aria-label": "Note target", class: "ch-target" }),
      text,
      h("button", { class: "small danger", "aria-label": "Remove note", onclick: () => { entry.notes.splice(i, 1); changed(true) } }, "×"),
    )
  }
  const det = h("details", { class: "changes", style: "flex-basis:100%" },
    h("summary", { class: "note" }, count ? `Changes & notes (${count})` : "Add changes or context notes"),
    h("div", { class: "ch-head" }, h("strong", {}, "Changes"), h("span", { class: "note" }, "Bonuses Foundry applies automatically. Type @ in a formula to pick a value.")),
    ...entry.changes.map(changeRow),
    h("button", { class: "small", onclick: () => { entry.changes.push({ target: "", type: "untyped", formula: "" }); keepOpen(det); changed(true) } }, "+ Change"),
    h("div", { class: "ch-head" }, h("strong", {}, "Context notes"), h("span", { class: "note" }, "Situational reminders shown on rolls in Foundry.")),
    ...entry.notes.map(noteRow),
    h("button", { class: "small", onclick: () => { entry.notes.push({ target: "", text: "" }); keepOpen(det); changed(true) } }, "+ Note"),
  )
  if (openEditors.has(entry)) det.open = true
  det.addEventListener("toggle", () => (det.open ? openEditors.add(entry) : openEditors.delete(entry)))
  return det
}
// which entries have their changes block open, kept out of the saved character
const openEditors = new WeakSet()
// re-render keeps the block open after adding a row
function keepOpen(det) {
  det.open = true
}

// ---------- export helpers ----------

function exportChanges(entry) {
  return (entry.changes ?? [])
    .filter((ch) => ch.target && String(ch.formula ?? "").trim())
    .map((ch) => ({ _id: randomId(8).toLowerCase(), formula: String(ch.formula).trim(), operator: ch.operator || "add", target: ch.target, type: ch.type || "untyped", priority: 0 }))
}
function exportNotes(entry) {
  return (entry.notes ?? []).filter((n) => n.target && String(n.text ?? "").trim()).map((n) => ({ text: String(n.text).trim(), target: n.target }))
}
